{
  "requirements": [
    {
      "text": "The system shall minimize energy consumption during operation by optimizing path and speed profiles, achieving at least a 15% reduction compared to baseline energy usage.",
      "kaos_level": "tactical",
      "rationale": "Energy efficiency is critical for reducing the carbon footprint of autonomous vehicles."
    },
    {
      "text": "The system shall utilize renewable energy sources for all charging stations within the operational design domain, ensuring at least 50% of energy is sourced renewably.",
      "kaos_level": "strategic",
      "rationale": "Using renewable energy reduces the overall carbon footprint of the autonomous driving system."
    },
    {
      "text": "The system shall implement lifecycle assessments for all components, ensuring that 80% meet sustainability criteria for resource impact.",
      "kaos_level": "strategic",
      "rationale": "Lifecycle resource impact is crucial for evaluating the sustainability of materials used in the system."
    },
    {
      "text": "The system shall achieve a minimum of 90% efficiency in energy recovery during vehicle braking maneuvers.",
      "kaos_level": "operational",
      "rationale": "Improving energy recovery during braking enhances overall energy efficiency, supporting sustainability goals."
    },
    {
      "text": "The system shall provide real-time monitoring of carbon emissions during operation, with a target of reducing emissions by 25% over five years.",
      "kaos_level": "tactical",
      "rationale": "Monitoring and reducing emissions are essential for improving the sustainability profile of the autonomous driving system."
    },
    {
      "text": "The system shall incorporate algorithms that prioritize energy-efficient routing, achieving a reduction in operational energy costs by at least 20%.",
      "kaos_level": "operational",
      "rationale": "Energy-efficient routing directly contributes to reducing the overall carbon footprint of the system."
    },
    {
      "text": "The system shall establish emergency protocols that minimize energy usage during critical failures, ensuring a reduction in unnecessary power consumption during incidents.",
      "kaos_level": "tactical",
      "rationale": "Minimizing energy usage during emergencies is vital for maintaining sustainability even in adverse situations."
    }
  ]
}
